# This workflow checks for @file documentation across popup helpers, entry points,
# models, search strategies, and views. It also highlights scoring pipeline steps
# so future tuning keeps parity with historical behaviour notes.

name: Claude Code Review

on:
  pull_request:
    branches: [main]
  push:
    branches: [main]

jobs:
  check-docs:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4

      - name: Set up Node
        uses: actions/setup-node@v4
        with:
          node-version: '20'

      - name: Check @file documentation
        run: |
          node <<'NODE'
          const fs = require('fs');
          const glob = require('glob');
          const files = glob.sync('**/*.js', { ignore: ['node_modules/**', '.git/**'] });
          const missing = [];
          files.forEach(file => {
            const content = fs.readFileSync(file, 'utf8');
            const firstComment = content.match(/\\/\\*\\*([\\s\\S]*?)\\*\\//);
            if (!firstComment || !/@file/.test(firstComment[1])) {
              missing.push(file);
            }
          });
          if (missing.length > 0) {
            console.error('Missing @file documentation in the following files:');
            missing.forEach(f => console.error('  ' + f));
            process.exit(1);
          } else {
            console.log('All files have @file documentation.');
          }
          NODE
        shell: bash
```

